JOIN courses c ON c.university_id = u.id AND c.code = v.code
JOIN terms t ON t.university_id = u.id AND t.code = v.term WHERE u.slug = 'ucf';

-- flags: rule-based (behind pace, failed prerequisite, seat risk, Foundation Exam window)
INSERT INTO student_flags (student_id, course_id, flag_type, severity, message)
SELECT s.id, c.id, v.ftype, v.sev, v.msg
FROM universities u CROSS JOIN (VALUES
  ('SYN-0003', NULL, 'behind_pace', 'high', 'About 4.2 terms behind a standard 8-term pace (68 of 114 modeled program credits done or in progress after 9 terms).'),
