  ('SYN-0006', 'MAC 2312', 'seat_risk', 'high', 'Only 2 open seats across 2 sections of MAC 2312 for Spring 2027.'),
  ('SYN-0009', 'COT 3100C', 'missing_prereq', 'high', 'COT 3100C: earned C- in Spring 2026; needs a retake. Blocks COP 3503C.'),
  ('SYN-0011', 'PHY 2053C', 'missing_prereq', 'high', 'PHY 2053C: earned F in Spring 2025; needs a retake. Blocks PHY 2054C, CNT 3004.'),
  ('SYN-0012', NULL, 'behind_pace', 'high', 'About 4.1 terms behind a standard 8-term pace (68 of 111 modeled program credits done or in progress after 9 terms).'),
