  ('SYN-0015', 'CGS 3763', 'missing_prereq', 'high', 'CGS 3763: earned D in Fall 2024; needs a retake. Blocks CNT 4603.'),
  ('SYN-0015', 'CGS 3763', 'seat_risk', 'high', 'Only 3 open seats across 1 section of CGS 3763 for Spring 2027.'),
  ('SYN-0017', 'EEL 3801C', 'missing_prereq', 'high', 'EEL 3801C: earned D in Spring 2025; needs a retake. Blocks COP 4600, EEL 4742C, EEL 4768, EEL 4781.'),
  ('SYN-0017', 'EEL 3801C', 'seat_risk', 'high', 'Only 1 open seat across 1 section of EEL 3801C for Spring 2027.'),
