) AS v(ext, code, ftype, sev, msg)
JOIN students s ON s.university_id = u.id AND s.external_id = v.ext
LEFT JOIN courses c ON c.university_id = u.id AND c.code = v.code WHERE u.slug = 'ucf';

-- advisor notes (fictional)
INSERT INTO advisor_notes (student_id, advisor_id, body)
SELECT s.id, s.advisor_id, v.body FROM universities u CROSS JOIN (VALUES
  ('SYN-0004', 'Met 10/02. Earned a D in COP 3502C last spring. Wants to retake in spring; was waitlisted this fall. Asked about summer options.'),
